/**
 * src/agents/tx-10-imp-1/prompts/action-05.ts
 * 
 * Action 5: メンバー別の習熟度と課題を自動判定し、フィードバック案を作成する
 * 
 * tx_10_imp_1 契約に基づき、初回報告データを分析してメンバー別フィードバック案を生成
 */

export const ACTION_05_PROMPT_VERSION = "1.0.0";

export interface Action05PromptInput {
  initialReportData: InitialReportRecord[];
  memberProfiles: MemberProfile[];
  adoptionContext: AdoptionContext;
  feedbackCriteria: FeedbackCriteria;
}

export interface InitialReportRecord {
  memberId: string;
  memberName: string;
  reportDate: string;
  submissionTime: string;
  dataQuality: "high" | "medium" | "low";
  completenessScore: number;
  issueCount: number;
  issueCategories: string[];
  reportContent: string;
  submissionDelayMinutes: number;
}

export interface MemberProfile {
  memberId: string;
  memberName: string;
  department: string;
  role: string;
  experienceLevel: "junior" | "mid" | "senior";
  previousToolExperience: boolean;
}

export interface AdoptionContext {
  adoptionPhase: "initial" | "early" | "established";
  trainingCompletionDate: string;
  organizationSize: number;
  targetAdoptionRate: number;
}

export interface FeedbackCriteria {
  excellenceThreshold: number;
  improvementThreshold: number;
  supportThreshold: number;
  dataQualityWeight: number;
  completenessWeight: number;
  timelinessWeight: number;
}

export interface MemberFeedbackAssessment {
  memberId: string;
  memberName: string;
  proficiencyLevel: "excellent" | "good" | "needs_improvement" | "needs_support";
  proficiencyScore: number;
  dataQualityScore: number;
  completenessScore: number;
  timelinessScore: number;
  strengths: string[];
  improvementAreas: string[];
  recommendedActions: string[];
  supportLevel: "none" | "light" | "moderate" | "intensive";
  estimatedHabitFormationDays: number;
}

export interface Action05PromptOutput {
  assessmentTimestamp: string;
  memberAssessments: MemberFeedbackAssessment[];
  overallAdoptionHealth: {
    averageProficiencyScore: number;
    excellentCount: number;
    goodCount: number;
    improvementCount: number;
    supportCount: number;
    recommendedInterventions: string[];
  };
  feedbackDeliveryPlan: {
    immediateActions: string[];
    weeklyFollowUpTopics: string[];
    escalationCandidates: string[];
  };
}

/**
 * buildAction05Prompt
 * 
 * 初回報告データを分析し、メンバー別の習熟度と課題を判定してフィードバック案を生成するプロンプトを構築
 * 
 * @param input - Action05PromptInput
 * @returns プロンプト文字列
 */
export function buildAction05Prompt(input: Action05PromptInput): string {
  const {
    initialReportData,
    memberProfiles,
    adoptionContext,
    feedbackCriteria,
  } = input;

  const memberMap = new Map(memberProfiles.map((m) => [m.memberId, m]));

  const assessments: MemberFeedbackAssessment[] = initialReportData.map(
    (report) => {
      const member = memberMap.get(report.memberId);
      if (!member) {
        throw new Error(`Member profile not found for ${report.memberId}`);
      }

      const dataQualityScore =
        report.dataQuality === "high"
          ? 100
          : report.dataQuality === "medium"
            ? 70
            : 40;

      const completenessScore = report.completenessScore * 100;

      const timelinessScore = Math.max(
        0,
        100 - (report.submissionDelayMinutes / 60) * 10
      );

      const proficiencyScore =
        dataQualityScore * feedbackCriteria.dataQualityWeight +
        completenessScore * feedbackCriteria.completenessWeight +
        timelinessScore * feedbackCriteria.timelinessWeight;

      let proficiencyLevel: "excellent" | "good" | "needs_improvement" | "needs_support";
      if (proficiencyScore >= feedbackCriteria.excellenceThreshold) {
        proficiencyLevel = "excellent";
      } else if (proficiencyScore >= feedbackCriteria.improvementThreshold) {
        proficiencyLevel = "good";
      } else if (proficiencyScore >= feedbackCriteria.supportThreshold) {
        proficiencyLevel = "needs_improvement";
      } else {
        proficiencyLevel = "needs_support";
      }

      const strengths: string[] = [];
      const improvementAreas: string[] = [];

      if (dataQualityScore >= 80) {
        strengths.push("高品質なデータ入力");
      } else {
        improvementAreas.push("データ品質の向上が必要");
      }

      if (completenessScore >= 80) {
        strengths.push("完全な報告内容");
      } else {
        improvementAreas.push("報告項目の漏れを減らす");
      }

      if (timelinessScore >= 80) {
        strengths.push("期限内の提出");
      } else {
        improvementAreas.push("提出タイミングの改善");
      }

      if (report.issueCount > 0) {
        strengths.push("課題の適切な報告");
      }

      const recommendedActions: string[] = [];
      if (proficiencyLevel === "excellent") {
        recommendedActions.push("継続的な優良事例として参考にする");
        recommendedActions.push("他メンバーへのメンタリング対象として検討");
      } else if (proficiencyLevel === "good") {
        recommendedActions.push("軽微な改善点を個別フィードバック");
      } else if (proficiencyLevel === "needs_improvement") {
        recommendedActions.push("改善ポイントを明確にして指導");
        recommendedActions.push("1週間後に進捗確認");
      } else {
        recommendedActions.push("集中的なサポートを提供");
        recommendedActions.push("操作方法の再確認");
        recommendedActions.push("毎日の進捗確認");
      }

      const supportLevel: "none" | "light" | "moderate" | "intensive" =
        proficiencyLevel === "excellent"
          ? "none"
          : proficiencyLevel === "good"
            ? "light"
            : proficiencyLevel === "needs_improvement"
              ? "moderate"
              : "intensive";

      const estimatedHabitFormationDays =
        proficiencyLevel === "excellent"
          ? 0
          : proficiencyLevel === "good"
            ? 3
            : proficiencyLevel === "needs_improvement"
              ? 7
              : 14;

      return {
        memberId: report.memberId,
        memberName: report.memberName,
        proficiencyLevel,
        proficiencyScore: Math.round(proficiencyScore),
        dataQualityScore,
        completenessScore,
        timelinessScore: Math.round(timelinessScore),
        strengths,
        improvementAreas,
        recommendedActions,
        supportLevel,
        estimatedHabitFormationDays,
      };
    }
  );

  const excellentCount = assessments.filter(
    (a) => a.proficiencyLevel === "excellent"
  ).length;
  const goodCount = assessments.filter(
    (a) => a.proficiencyLevel === "good"
  ).length;
  const improvementCount = assessments.filter(
    (a) => a.proficiencyLevel === "needs_improvement"
  ).length;
  const supportCount = assessments.filter(
    (a) => a.proficiencyLevel === "needs_support"
  ).length;

  const averageProficiencyScore =
    assessments.length > 0
      ? Math.round(
          assessments.reduce((sum, a) => sum + a.proficiencyScore, 0) /
            assessments.length
        )
      : 0;

  const recommendedInterventions: string[] = [];
  if (supportCount > 0) {
    recommendedInterventions.push(
      `${supportCount}名のメンバーに集中的なサポートが必要`
    );
  }
  if (improvementCount > 0) {
    recommendedInterventions.push(
      `${improvementCount}名のメンバーに改善指導を実施`
    );
  }
  if (averageProficiencyScore < 70) {
    recommendedInterventions.push("全体的な研修内容の見直しを検討");
  }

  const escalationCandidates = assessments
    .filter((a) => a.proficiencyLevel === "needs_support")
    .map((a) => a.memberName);

  const immediateActions: string[] = [];
  if (escalationCandidates.length > 0) {
    immediateActions.push(
      `${escalationCandidates.join("、")}に対して個別サポートを開始`
    );
  }
  immediateActions.push("全メンバーへ初回フィードバックを配信");
  immediateActions.push("1週間後に進捗確認ミーティングを実施");

  const weeklyFollowUpTopics: string[] = [
    "データ品質の向上方法",
    "報告項目の完全性確認",
    "提出期限の厳守",
    "課題報告の具体性向上",
  ];

  const promptText = `
# Action 5: メンバー別習熟度判定とフィードバック案作成

## 入力データ
- 初回報告データ件数: ${initialReportData.length}
- 対象メンバー数: ${memberProfiles.length}
- 導入フェーズ: ${adoptionContext.adoptionPhase}
- 研修完了日: ${adoptionContext.trainingCompletionDate}

## 分析結果

### メンバー別習熟度評価
${assessments
  .map(
    (a) => `
#### ${a.memberName} (ID: ${a.memberId})
- 習熟度レベル: ${a.proficiencyLevel}
- 総合スコア: ${a.proficiencyScore}/100
  - データ品質: ${a.dataQualityScore}/100
  - 完全性: ${a.completenessScore}/100
  - 時間厳守: ${a.timelinessScore}/100
- 強み: ${a.strengths.join("、")}
- 改善領域: ${a.improvementAreas.join("、")}
- 推奨アクション: ${a.recommendedActions.join("、")}
- サポートレベル: ${a.supportLevel}
- 習慣形成予想日数: ${a.estimatedHabitFormationDays}日
`
  )
  .join("\n")}

### 全体的な導入状況
- 平均習熟度スコア: ${averageProficiencyScore}/100
- 優秀: ${excellentCount}名
- 良好: ${goodCount}名
- 改善必要: ${improvementCount}名
- サポート必要: ${supportCount}名

### 推奨される介入施策
${recommendedInterventions.map((i) => `- ${i}`).join("\n")}

### フィードバック配信計画
- 即座のアクション: ${immediateActions.map((a) => `${a}`).join("、")}
- 週次フォローアップテーマ: ${weeklyFollowUpTopics.join("、")}
- エスカレーション対象: ${escalationCandidates.length > 0 ? escalationCandidates.join("、") : "なし"}

## 指示
以下の観点から、メンバー別フィードバック案を精緻化してください:
1. 各メンバーの習熟度レベルが適切に判定されているか確認
2. 改善領域と推奨アクションが具体的で実行可能か検証
3. サポートレベルが適切に設定されているか確認
4. 全体的な導入状況の健全性を評価
5. 部長への報告内容を明確にする
`;

  return promptText;
}
